INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Surmount: A Mountain Climbing Adventure', 'Surmount is a free-flowing, physics-based platforming adventure where you’ll experience the joys of mountain climbing. Make your perilous ascent through the various handcrafted and procedurally generated challenges of Mount Om, all the while following a silly story with eccentric folks along the way. Master your own unique style of climbing either alone or with a friend, upgrade and customize your climber to stand a better chance, and maybe just maybe, you''ll be the first ever to reach the top!' FROM games WHERE igdb_id = 224185 ON CONFLICT (game_id, language_code) DO NOTHING;
