INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beasties of Greenhollow', 'Beasties of Greenhollow is a strategic turn based team building game that features a collection of cute creatures based of Scottish mythology. Explore a mysterious realm of fairies, elves, magic, and creatures while fighting to the center of this hidden realm at the request of a mysterious masked figure. What are Shellycoat’s true intentions?' FROM games WHERE igdb_id = 299465 ON CONFLICT (game_id, language_code) DO NOTHING;
