INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lexibook-batman-compact-cyber-arcade-portable-console', 304232, '2024-03-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8amt.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lexibook Batman Compact Cyber Arcade Portable Console', 'Introducing the Lexibook Batman Compact Cyber Arcade Portable Console, your gateway to a world of endless entertainment! With 150 exhilarating games at your fingertips, including 10 action-packed Batman adventures and 140 classic favorites spanning sports, logic, adventure, platforms, and more, this pocket-sized powerhouse guarantees hours of non-stop fun for everyone. Hunt menacing monsters, escape perilous zones, score incredible goals, and race to victory in wild competitions, all on the vibrant 2.5" LCD color screen that brings every game to life with stunning visuals. Our portable console isn''t just about gaming; it''s a complete sensory experience. Immerse yourself in the Batman universe with its captivating design, celebrating the Dark Knight and enhancing every gaming session. The built-in speaker and volume control allow you to enjoy the immersive soundscapes without disturbance, making this console the ultimate gaming companion for on-the-go adventures. The Lexibook Batman Compact Cyber Arcade Portable Console isn''t just a gaming device; it''s a statement. Perfectly sized to accompany you wherever you roam, it fits effortlessly in your pocket or bag, ensuring that the excitement is always within reach. Whether you''re a seasoned gamer or a casual player, this console offers something for everyone, from adrenaline-pumping action to brain-teasing challenges. Experience the future of gaming with this battery-operated wonder, and elevate your leisure time to a whole new level. With Lexibook Compact Cyber Arcade Portable Console, you''re not just buying a toy; you''re investing in unforgettable memories and endless entertainment. Don''t miss your chance to own this unique piece of gaming history—grab yours now and embark on an epic adventure that will leave you craving for more!' FROM games WHERE igdb_id = 304232 ON CONFLICT (game_id, language_code) DO NOTHING;
