INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gisselle''s Adventure', 'A serious video game about social anxiety, narrated from the perspective of Gisselle, a young student who, after years of homeschooling, must face the real world and her own fears. Through a blend of visual novel elements, RPG, and platforming, the player will accompany Gisselle in her struggle to overcome her social phobia in a story that fuses the everyday with the surreal.' FROM games WHERE igdb_id = 335737 ON CONFLICT (game_id, language_code) DO NOTHING;
