INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'What the Luck?', '"What the Luck?: CoOp Defense" (also known as Lucky Defense!) is a mobile tower defense game heavily centered on RNG (random number generation) and luck-based mechanics. Developed by 111percent, the game challenges players to defend against waves of monsters using summoned units, with success determined by whether they "beat the odds".' FROM games WHERE igdb_id = 382857 ON CONFLICT (game_id, language_code) DO NOTHING;
