INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cozy-room-decorator', 269688, '2024-03-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7655.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2kau.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cozy Room Decorator', 'Step into the world of Cozy Room Decorator where you’re the chief curator of cozy and it’s up to you to define what cozy means. Whether that means a lived-in kitchen space filled with sweets, or a tech-laden game room, the combinations are waiting to be explored. Dive into a world of boundless imagination and creativity with a treasure trove of hundreds of items, each brimming with endless possibilities. Equipped with your very own room, this whimsical isometric room design game invites you to unleash your inner interior decorator.' FROM games WHERE igdb_id = 269688 ON CONFLICT (game_id, language_code) DO NOTHING;
