INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'IF: Imaginary Friends', 'The main character, a young boy named Croqui, is reunited with the imaginary friends he created in his infancy due to a mental regression caused by the birth of his younger sister. Fearing that he will be forgotten again, the friends try to trap him in their imaginary world by playing games with him! You are Croqui and you will win the game with your friends. An adventure game with an atmosphere like a picture book or a painting, featuring unique imaginary friends.' FROM games WHERE igdb_id = 324800 ON CONFLICT (game_id, language_code) DO NOTHING;
