INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Punch Monkey', 'You''re a broke loner who lives in a crappy apartment. Crime, drugs and alcohol run rampant in your neighborhood. You dream of a better life but it''s out of reach. That is, until you see an ad on TV for a big fight with a cash prize! You set out to claim the prize, but you have to make your way through hordes of unsavory crackheads and worthless bums. Are you up to the challenge?' FROM games WHERE igdb_id = 316512 ON CONFLICT (game_id, language_code) DO NOTHING;
