INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slime 3k: Demake', 'A blob of goo, initially used to nourish artificial humans, has become sentient and risen up against its creator—the Despot, an evil AI and the unfortunate ruler of the world in the year 3000! The future is bleak, and humanity is beyond redemption, but at least you have the power to save yourself. This demake is a mini-version of the game Slime 3K: Rise Against Despot.' FROM games WHERE igdb_id = 322759 ON CONFLICT (game_id, language_code) DO NOTHING;
