INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galactic Loader', 'Galactic Loader is an action-platformer about a space loader who is forgotten on a hostile alien planet which is abandoned by people. The game has various power-ups, big bosses and many monsters that the player needs to defeat. On his journey, the hero finds leftover equipment that provides new abilities for the player. Fight through hordes of alien, giant monsters and escape the planet!' FROM games WHERE igdb_id = 324304 ON CONFLICT (game_id, language_code) DO NOTHING;
