INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jorel''s Brother and the Most Important Game of the Galaxy: Complete Edition', 'Based on the award-winning Brazilian animation Jorel''s Brother, Jorel''s Brother and the Most Important Game of the Galaxy is a point-and-click adventure about an eight-year-old boy who lives with his eccentric family in the shadow of Jorel, his handsome and popular brother. Users control Jorel’s Brother as he faces alien spaceships, authoritarian clowns, bureaucracy, driving tests, and avocado smoothies in three episodes full of humor and action.' FROM games WHERE igdb_id = 297303 ON CONFLICT (game_id, language_code) DO NOTHING;
