INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ametrine Dreams', 'After an unfortunate accident involving Kamishiro Rui, Rui''s robots and machines, Tenma Tsukasa is sent on a confusing journey through different dimensions. But to make matters worse, in every world Tsukasa visits, he finds the familiar face of his director. And to add to the disorientation, every version of Rui is wildly different. It wouldn''t be Rui without a secret, no? Download and play as Tsukasa to uncover the endless mysteries surrounding all the different Ruis!' FROM games WHERE igdb_id = 382192 ON CONFLICT (game_id, language_code) DO NOTHING;
