INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moon River', 'Moon River is an atmospheric experience with very light narrative and gameplay elements. You''ll explore different areas of Elapse Island, searching for ways to dispel dark shadows that block your path along the river. This is not intended to be thrilling or challenging, but rather to evoke emotions through the colors and sounds of this environment.' FROM games WHERE igdb_id = 298303 ON CONFLICT (game_id, language_code) DO NOTHING;
