INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shepherd', 'Shepherd is a first-person simulator puzzle game where you play as Jody Sima, the handler of a special task group codenamed “Shepherd”. Using a combination of radio conversation, live-positioning map, photo receiver, and a field manual, you will guide your teammates through a series of seemingly bizarre events and simulations, unveil the secrets of the facility, and (try to) bring everyone safely back home.' FROM games WHERE igdb_id = 361423 ON CONFLICT (game_id, language_code) DO NOTHING;
