INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Combo Fishing', 'There are 16 fish to collect in this collectathon made for the Gameboy Color! The goal is to complete the museum, and to buy all of the extra goodies that you can from the Frog Shop! You can earn Frog Tokens by fishing with each catch! Your progress autosaves. You can also view the lectern in the museum to see how many of each fish you''ve collected. If it seems like you can''t interact with something, you could be facing the wrong way, try pressing the direction again.' FROM games WHERE igdb_id = 340206 ON CONFLICT (game_id, language_code) DO NOTHING;
