INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubble Aim', 'Bubble Aim is an exciting game where bubbles of various colors and sizes descend from the sky. The player must shoot these bubbles, causing them to either burst or split into smaller bubbles. Each successful shot earns the player points. The objective is to shoot as many bubbles as possible without letting them fall to the ground. The game is endless, challenging players to achieve the highest score possible by continuously popping bubbles. How many bubbles can you shoot?' FROM games WHERE igdb_id = 316555 ON CONFLICT (game_id, language_code) DO NOTHING;
