INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Physiblock', 'A physics-based first person parkour puzzle game, go through various tests as a test robot and be careful not to fall into the water, not to get caught by other robots and to use objects that will help you cross carefully, the game will be released on itch.io on September 5th, would you like to see what life is like through the eyes of a robot? Then grab your computers and wait for September 5th!' FROM games WHERE igdb_id = 315426 ON CONFLICT (game_id, language_code) DO NOTHING;
