INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghostware: Arena of the Dead', 'Ghostware is a retro-fps combining the lore-heavy plot and exploration of adventure games with the fast action of ''90s shooters. You and other ghosts have been trapped inside an arena FPS created by a wizard''s unwillingness to overcome his nostalgia. Escape the past, shoot your way out.' FROM games WHERE igdb_id = 203733 ON CONFLICT (game_id, language_code) DO NOTHING;
