INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MGDC Minigame Collection', 'The MGDC Minigame Collection is what it says on the tin: A collection of our club''s previous minigames and small projects for you to enjoy. The Collection includes 19 separate titles, ranging from simulators, racing games, shooters, and more. Each game was crafted in a limited time frame by students in the Miami University Game Design club, working on enhancing the skills of members, and having fun while doing it.' FROM games WHERE igdb_id = 341230 ON CONFLICT (game_id, language_code) DO NOTHING;
