INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Temple of Shadows', 'Embark on an epic adventure as Sabastian Harrington, a passionate archeology grad student turned explorer, in search of his missing professor. Six weeks ago, Dr. Albert J. Montgomery III announced the discovery of a hidden temple, but he never returned. Now, Sabastian must dive into ancient temple ruins, solve intricate puzzles, and uncover hidden secrets. Will you reveal the mysteries within the Temple of Shadows?
