INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crypt''s Game', 'You are out in the woods, in search of the entity known as Crypt. Stopping in your tracks, you see it approaching. You take aim with your shotgun, intending to kill it, when suddenly the ground beneath you gives way, dropping you down into the earth. You find yourself trapped in Crypts dungeon where it will play a twisted game of Cat and Mouse. Killing it is the only way out, will you survive?' FROM games WHERE igdb_id = 326512 ON CONFLICT (game_id, language_code) DO NOTHING;
