INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dave the Diver: Anniversary Edition', 'Dave the Diver is an action-adventure and management simulation game developed by Mintrocket. In the game, players control Dave, who spends his days diving into underwater environments to catch fish and gather resources, and his nights managing a sushi restaurant. The gameplay combines real-time underwater exploration and combat with restaurant management mechanics.
