INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stewie Kills the Griffins!', 'Damn you vile woman! In fact, DAMN THE WHOLE LOT OF THEM for that matter! Stewie Griffin has finally had it with the family, and he''s looking to make good on some longstanding threats! Paint Quahog RED in this over the top, visceral cartoon murder sim that continues in the bloody footsteps established in the prior "KILLS" game series!' FROM games WHERE igdb_id = 327490 ON CONFLICT (game_id, language_code) DO NOTHING;
