INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-witch-in-time-yamada-kun-to-nananin-no-majo', 292009, '2024-03-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7wru.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr8tj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Witch in Time: Yamada-kun to Nananin no Majo', 'At Suzaku High School, there has been generation after generation of witches that hold special powers. Ryu Yamada holds the special power to copy a witch''s power and he''s been using this to solve the many issues that pop-up at the school. One day, Ryu and his friends are hanging out at the Occult Club as usual. But when Miyabi brings up a rumor involving time travel, Ryu brushes it off as being unrelated to witches and their powers. On the way home from school, just outside the gates, Ryu feels someone tap on his shoulder. He turns around, but there''s nobody there. Thinking it must have been his imagination, he continues on his way home only to find his house is gone! It turns out, he''s travelled in time!' FROM games WHERE igdb_id = 292009 ON CONFLICT (game_id, language_code) DO NOTHING;
