INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mushroom Season', 'Mushroom Season is a mushroom picking simulator! Customize your character and immerse yourself in the competitive world of mushroom picking. Explore rich forests filled with diverse mushrooms—some delicious, some deadly. Master the art of identification, tackle survival challenges, and engage in fun side quests. Drive vehicles to cover more ground and aim for the prestigious mushroom picking trophy. Ready to prove you''re the best forager out there? Dive in and find out!' FROM games WHERE igdb_id = 313599 ON CONFLICT (game_id, language_code) DO NOTHING;
