INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kūnlún', '"Kūnlún" is developed using the Unreal 4 engine. This series tells about the future war between humans and artificial intelligence aggregates and multi-alien races from extragalactic galaxies. The game builds a brand new sci-fi world from a unique perspective. Players will play an interstellar ranger in the world of "Kūnlún", and use the unique interactive system to take risks in the vast sci-fi world with their partners.' FROM games WHERE igdb_id = 154107 ON CONFLICT (game_id, language_code) DO NOTHING;
