INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Azura''s Crystals', 'Embark on an enchanting quest as Azura, a spirited heroine, and discover a world of ancient mysticism. Forge unbreakable bonds with mythical creatures using the power of Primalis Crystals. Traverse breathtaking landscapes, make difficult choices, and uncover the secrets that shape your destiny.' FROM games WHERE igdb_id = 318352 ON CONFLICT (game_id, language_code) DO NOTHING;
