INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kai-Ri-Sei Million Arthur: Ring', 'Million Arthur Ring is the latest sequel in the Million King Arthur series, bringing back the familiar four-Arthurs gameplay and four-player co-op mode. The game retains the classic card battle mechanics, including attribute weaknesses and card chain buffs, while introducing new strategic elements through CCG-style turn-based gameplay. Players can collect and customize various cards to build their ideal team.' FROM games WHERE igdb_id = 318432 ON CONFLICT (game_id, language_code) DO NOTHING;
