INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ling Hun', 'A 2D Platformer Game were Jumping is not affected by gravity (that''s what happens when you got your soul stolen). Master the jump to succeed in every level. Enjoy the classic Pixel Art with a mix of Asian ink style in the Background. Change the pace of the game to adapt it to your gamestyle.' FROM games WHERE igdb_id = 277452 ON CONFLICT (game_id, language_code) DO NOTHING;
