INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soko Banana', '"Soko Banana" is a puzzle game developed for the Nintendo Entertainment System (NES), inspired by the classic Sokoban concept. Players guide the young monkey, Skid, through banana warehouses across five distinct islands, each introducing unique mechanics such as pits, breakable blocks, and teleporters. The objective is to maneuver banana crates to designated exits while collecting bananas to unlock bonus levels. The game offers 55 levels in total, including hidden secrets.' FROM games WHERE igdb_id = 333712 ON CONFLICT (game_id, language_code) DO NOTHING;
