INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loop', 'Loop is a visual novel set in a dark Irish Forest. Deirdre is set to find her husband who was sworn to become the Forest King. But it’s not easy for a human to walk in the magical realm. What will Deirdre learn about this other world? What will she find out about herself?' FROM games WHERE igdb_id = 327298 ON CONFLICT (game_id, language_code) DO NOTHING;
