INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Flight Simulator 2024: Premium Deluxe Edition', 'Pursue your aviation career throughout the world with dynamically-generated missions ranging from Medevac and Search & Rescue to Aerial Firefighting and Passenger Transport. Compete against other pilots in the iconic Reno and Red Bull Air Races. Enhanced physics and aircraft systems and a groundbreaking flight planner create an unparalleled simulation experience. Explore the most detailed digital twin of the world to date with real-time air and ship traffic and a vast array of animals. Set out on your global adventure with our largest fleet of aircraft as Microsoft Flight Simulator 2024 takes simulation to new heights of authenticity and realism.' FROM games WHERE igdb_id = 331262 ON CONFLICT (game_id, language_code) DO NOTHING;
