INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SMYS: Show Me Your Stairs', 'SMYS is a 2-4 player local-multiplayer party game. Challenge your friends in this building race to the top! Gather blocs in various minigames and then use them to build your stairs as fast as possible, use your special items wisely to disturb your friends'' minds and capture the flag first.' FROM games WHERE igdb_id = 199437 ON CONFLICT (game_id, language_code) DO NOTHING;
