INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sicko Sanctum 2', 'Enemies are weapons. Style is power. Your only goal, total violence. SICKO SANCTUM 2 is an innovative score-attack movement-shooter crafted from the design lessons of modern classics such as ULTRAKILL and HYPER DEMON. Featuring a simple player move-set in combination with synergistic enemy design, SICKO SANCTUM 2 represents the cutting-edge of digitized violence.' FROM games WHERE igdb_id = 273904 ON CONFLICT (game_id, language_code) DO NOTHING;
