INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nancy-drew-mystery-of-the-seven-keys', 262197, '2024-05-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8avf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3kep.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nancy Drew: Mystery of the Seven Keys', 'Get ready for a thrilling blend of adventure, mystery, and history in the latest installment of the award-winning Nancy Drew game series – Nancy Drew: Mystery of the Seven Keys! This all-new 3D game experience transports players to the heart of the historic city of Prague as they assume the role of famous detective Nancy Drew. Tasked with uncovering the truth behind the theft of a client’s heirloom necklace, players will navigate and sleuth through the beautiful city’s mysterious old-world environments. Encounter challenging puzzles, decode riddles, and discover clues entwined with medieval legends, alchemy, and lore. As the investigation deepens, Nancy uncovers a sinister web of cybercrime. Players must outwit devious suspects and use their detective skills to unravel a mystery threatening the city’s Bohemian heritage. Danger and intrigue at every turn add to the suspense as the criminals stop at nothing to prevent you from bringing the truth to light. Your investigative and critical thinking skills are crucial to solving the case and discovering the real mystery behind the legend of the seven keys!' FROM games WHERE igdb_id = 262197 ON CONFLICT (game_id, language_code) DO NOTHING;
