INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loveland''s Leap', 'Leap into the forest in this 2d puzzle platformer! Swing through the woods, find flies, and solve simple brain teasers. Let the trees envelope you as the water colored backgrounds and kalimba themed music create an unforgettable story book like atmosphere.' FROM games WHERE igdb_id = 341183 ON CONFLICT (game_id, language_code) DO NOTHING;
