INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yatagarasu Enter the Eastward', 'Following the success of "Yatagarasu Attack on Cataclysm," the new game introduces a parallel world filled with fresh characters and meticulously optimized gameplay. The game combines high-quality pixel graphics with a straightforward gameplay style accessible to all players. Key features include a core blocking mechanic, a simple yet deep game system, a live commentary feature, and robust network battle support.' FROM games WHERE igdb_id = 282127 ON CONFLICT (game_id, language_code) DO NOTHING;
