INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Corgi Knight', 'The Corgi Knight is about a corgi who starts out as a simple apple-picker, in a simple corgi town. No one expects much greatness from this little corgi, but when danger strikes, he finds himself in the midst of an epic adventure to save not only his village, but much, much more.' FROM games WHERE igdb_id = 375505 ON CONFLICT (game_id, language_code) DO NOTHING;
