INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gold and Glory', 'A lightweight medieval hero-based PvP dungeon explorer blending battle-royale, MOBA-style hero selection, and extraction mechanics. In short 5-minute runs players choose legendary heroes, team up or compete to clear dungeons, face bosses, and steal or lose loot based on success. Features ranked PvP, guild play, seasonal events and new heroes, plus device-friendly optimization for low-end phones.' FROM games WHERE igdb_id = 357523 ON CONFLICT (game_id, language_code) DO NOTHING;
